JSON.stringify((function(){
    const R=(e)=>{const r=e.getBoundingClientRect();return {l:Math.round(r.left),t:Math.round(r.top),r:Math.round(r.right),b:Math.round(r.bottom)};};
    const out=[...document.querySelectorAll('[data-im="connect-point"]')].map(p=>{const r=p.getBoundingClientRect();const x=Math.round(r.left+r.width/2),y=Math.round(r.top+r.height/2);const el=document.elementFromPoint(x,y);return {cls:p.className,x,y,hitTag:el?el.tagName:null,hitIm:el&&el.getAttribute?el.getAttribute('data-im'):null,hitCls:el?String(el.className):null,hitRect:el?R(el):null,hitText:el?(el.textContent||'').slice(0,30):null};});
    return {out, panels:{chat: (function(){const e=document.querySelector('[data-im="chat-panel"]');return e?R(e):null;})(), batch: (function(){const e=document.querySelector('[data-im="batch-list"]');return e?R(e):null;})()}};
  })())
